import { notFound, redirect } from "next/navigation";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { ResumeStudio } from "@/components/studio/ResumeStudio";
import { ResumeData, defaultContactInfo, defaultFormatting } from "@/lib/types/resume";

export default async function StudioPage({ params }: { params: Promise<{ id: string }> }) {
  const session = await getServerSession(authOptions);

  if (!session || !session.user || !session.user.id) {
    redirect("/login");
  }

  const { id } = await params;

  const resume = await prisma.resume.findUnique({ where: { id } });

  if (!resume) notFound();
  if (resume.userId !== session.user.id) redirect("/dashboard");

  const initialData: ResumeData = {
    id: resume.id,
    userId: resume.userId,
    name: resume.name,
    templateId: resume.templateId,
    contact: (resume.contact as any) || defaultContactInfo,
    summary: resume.summary || "",
    experience: (resume.experience as any) || [],
    education: (resume.education as any) || [],
    skills: (resume.skills as any) || [],
    projects: (resume.projects as any) || [],
    customSections: (resume.customSections as any) || [],
    sectionOrder: (resume.sectionOrder as any) || ["experience", "education", "skills", "projects", "customSections"],
    sectionVisibility: (resume.sectionVisibility as any) || {
      experience: true, education: true, skills: true, projects: true, customSections: true,
    },
    formatting: (resume.formatting as any) || defaultFormatting,
    createdAt: resume.createdAt.toISOString(),
    updatedAt: resume.updatedAt.toISOString(),
  };

  return <ResumeStudio initialData={initialData} />;
}

import { NextRequest, NextResponse } from "next/server";
import { PDFParse } from "pdf-parse";
import { GoogleGenAI, Type } from "@google/genai";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";

function cleanText(t: string) {
  return t.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
}

export async function POST(req: NextRequest) {
  let reservedUserId: string | null = null;

  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user?.email) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const result = await prisma.$transaction(async (tx) => {
      const uRes = await tx.$queryRaw<any[]>`
        SELECT id, plan, "monthlyParseCount", "lastMonthlyReset", "planExpiresAt"
        FROM "resumeforge"."User" 
        WHERE email = ${session.user.email} 
        FOR UPDATE
      `;
      const u = uRes[0];
      if (!u) return { error: "User not found", status: 404 };

      const now = new Date();
      let currentCount = u.monthlyParseCount;

      if (u.lastMonthlyReset) {
        const lastReset = new Date(u.lastMonthlyReset);
        if (lastReset.getMonth() !== now.getMonth() || lastReset.getFullYear() !== now.getFullYear()) {
          currentCount = 0;
        }
      } else {
        currentCount = 0;
      }

      // JIT Expiration Check
     // JIT Expiration Check
let effectivePlan = u.plan;
if (u.plan === "PRO" && u.planExpiresAt) {
  const expiresAt = new Date(u.planExpiresAt);
  if (expiresAt < now) {
    effectivePlan = "FREE";
  }
}

// ======================================================
// DEBUG LOGS
// ======================================================
console.log("========================================");
console.log("PARSE LIMIT CHECK");
console.log("User:", session.user.email);
console.log("Plan in DB:", u.plan);
console.log("Effective Plan:", effectivePlan);
console.log("Monthly Parse Count (DB):", u.monthlyParseCount);
console.log("Current Count:", currentCount);
console.log("Last Monthly Reset:", u.lastMonthlyReset);
console.log("Plan Expires At:", u.planExpiresAt);
console.log(
  "Limit Reached:",
  effectivePlan === "FREE" && currentCount >= 5
);
console.log("========================================");

if (effectivePlan === "FREE" && currentCount >= 5) {
  console.log("Returning LIMIT_REACHED (403)");
  return { error: "LIMIT_REACHED", status: 403 };
}
      // Eagerly increment to prevent race conditions during the slow Gemini API call
      await tx.user.update({
        where: { id: u.id },
        data: {
          monthlyParseCount: currentCount + 1,
          lastMonthlyReset: now,
        }
      });

      return { success: true, user: u };
    });

    if (result.error) {
      return NextResponse.json({ error: result.error }, { status: result.status });
    }

    reservedUserId = result.user.id;

    const formData = await req.formData();
    const file = formData.get("file") as File | null;

    if (!file) {
      return NextResponse.json({ error: "No file uploaded" }, { status: 400 });
    }

    if (file.type !== "application/pdf") {
      return NextResponse.json({ error: "Only PDF files are supported" }, { status: 400 });
    }

    if (file.size > 5 * 1024 * 1024) {
      return NextResponse.json({ error: "File too large. Max 5MB." }, { status: 400 });
    }

    // 1. Extract raw text from PDF
    const uint8 = new Uint8Array(await file.arrayBuffer());
    const parser = new PDFParse({ data: uint8, verbosity: 0 });
    const textResult = await parser.getText();
    await parser.destroy();

    const rawText = cleanText(textResult.text);

    if (!rawText || rawText.trim().length < 50) {
      return NextResponse.json({ error: "Could not extract text from this PDF. It might be an image or scanned document." }, { status: 400 });
    }

    // 2. Process with Gemini API
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return NextResponse.json({ error: "GEMINI_API_KEY is not configured on the server. Please add it to your .env file." }, { status: 500 });
    }

    const ai = new GoogleGenAI({ apiKey });

    // Define the JSON schema matching our frontend's expected format
    const responseSchema = {
      type: Type.OBJECT,
      properties: {
        contact: {
          type: Type.OBJECT,
          properties: {
            fullName: { type: Type.STRING, description: "Full name of the candidate" },
            jobTitle: { type: Type.STRING, description: "Current or primary job title" },
            email: { type: Type.STRING },
            phone: { type: Type.STRING },
            location: { type: Type.STRING },
            linkedin: { type: Type.STRING },
            website: { type: Type.STRING },
          },
        },
        summary: {
          type: Type.STRING,
          description: "A professional summary or objective, typically 2-3 sentences.",
        },
        experience: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              company: { type: Type.STRING },
              position: { type: Type.STRING },
              startDate: { type: Type.STRING, description: "e.g. Jan 2020" },
              endDate: { type: Type.STRING, description: "e.g. Dec 2022 or Present" },
              current: { type: Type.BOOLEAN, description: "True if currently working here" },
              location: { type: Type.STRING },
              description: { type: Type.STRING, description: "Bulleted or paragraph description of responsibilities" },
            },
            required: ["company", "position"],
          },
        },
        education: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              school: { type: Type.STRING },
              degree: { type: Type.STRING },
              fieldOfStudy: { type: Type.STRING },
              startDate: { type: Type.STRING },
              endDate: { type: Type.STRING },
              location: { type: Type.STRING },
              description: { type: Type.STRING },
            },
            required: ["school", "degree"],
          },
        },
        skills: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              level: { type: Type.STRING, description: "e.g. Beginner, Intermediate, Expert" },
            },
            required: ["name"],
          },
        },
        projects: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              url: { type: Type.STRING },
              technologies: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
              },
            },
            required: ["name"],
          },
        },
      },
    };

    const prompt = `You are an expert resume parser. I will provide you with the raw extracted text from a PDF resume.
Your task is to meticulously extract the data and structure it into the provided JSON schema.
Ensure you categorize the data correctly into contact information, summary, work experience, education, skills, and projects.
If a piece of information is missing, leave it as an empty string or empty array.
If the resume uses non-standard headings, do your best to infer the correct category.
CRITICAL FORMATTING INSTRUCTION: For any 'description' fields (like in experience, education, or projects), if the original resume uses bullet points, you MUST format the output as an HTML <ul> list with <li> items. If it uses paragraphs, use <p> tags. Do NOT use markdown.
RAW RESUME TEXT:
----------------
${rawText}
----------------
`;

    const response = await ai.models.generateContent({
      model: 'gemini-flash-latest',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: responseSchema,
        temperature: 0.1,
      },
    });

    const parsedData = JSON.parse(response.text || "{}");

    // Helper to format newlines or markdown bullets into proper HTML for the frontend
    const formatDescriptionToHTML = (desc: any) => {
      if (!desc) return "";

      // If Gemini somehow returned an array of strings
      if (Array.isArray(desc)) {
        return `<ul>${desc.map(d => `<li>${d}</li>`).join('')}</ul>`;
      }

      if (typeof desc !== 'string') return "";

      if (desc.includes('<ul>') || desc.includes('<p>')) return desc; // Already HTML
      const lines = desc.split('\n').map((l: string) => l.trim()).filter(Boolean);
      if (lines.length > 1 || lines[0]?.match(/^[-*•]/)) {
        const listItems = lines.map((l: string) => `<li>${l.replace(/^[-*•]\s*/, '')}</li>`);
        return `<ul>${listItems.join('')}</ul>`;
      }
      return `<p>${desc}</p>`;
    };

    // Add unique IDs and format descriptions
    const processItems = (arr: any[]) => (arr || []).map((item: any) => {
      const newItem = { ...item, id: crypto.randomUUID() };
      if (newItem.description) {
        newItem.description = formatDescriptionToHTML(newItem.description);
      }
      return newItem;
    });

    const finalParsed = {
      contact: parsedData.contact || {},
      summary: (parsedData.summary || "").substring(0, 600) + (parsedData.summary?.length > 600 ? "..." : ""),
      experience: processItems(parsedData.experience),
      education: processItems(parsedData.education),
      skills: processItems(parsedData.skills),
      projects: processItems(parsedData.projects),
    };

    // Usage was already eagerly incremented safely in the transaction above.

    console.log("======================================================");
    console.log("STAGE 1: Gemini Response (Raw JSON)");
    console.log("Summary:", !!parsedData.summary);
    console.log("Experience Length:", (parsedData.experience || []).length);
    console.log("Education Length:", (parsedData.education || []).length);
    console.log("Skills Length:", (parsedData.skills || []).length);
    console.log("Projects Length:", (parsedData.projects || []).length);
    console.log("CustomSections Length:", 0);
    console.log("======================================================");

    return NextResponse.json({ success: true, parsed: finalParsed });
  } catch (err: any) {
    console.error("PDF parse error:", err);

    // Rollback the eager increment if the parsing fails
    if (typeof reservedUserId === "string") {
      try {
        await prisma.user.update({
          where: { id: reservedUserId },
          data: { monthlyParseCount: { decrement: 1 } }
        });
      } catch (rollbackErr) {
        console.error("Failed to rollback usage limit:", rollbackErr);
      }
    }

    return NextResponse.json({ error: "Failed to parse PDF: " + (err?.message || "unknown error") }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { stripe } from "@/lib/stripe";
import { razorpay } from "@/lib/razorpay";

function sanitizeRazorpayCustomerName(name: string | null | undefined): string {
  if (!name) return "Reziyume User";

  // Remove unwanted characters (keep letters, numbers, spaces, hyphen, apostrophe, period)
  let sanitized = name.replace(/[^\p{L}\d \-'\.]/gu, "");

  // Collapse multiple spaces and trim
  sanitized = sanitized.replace(/\s+/g, " ").trim();

  return sanitized || "Reziyume User";
}

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || !session.user?.email) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const { country } = await req.json();

    if (country === "IN") {
      // Razorpay Subscription
      let razorpayCustomerId = user.razorpayCustomerId;

      // Create Razorpay customer if it doesn't exist
      if (!razorpayCustomerId) {
        const sanitizedName = sanitizeRazorpayCustomerName(session.user.name);

        console.log("=== RAZORPAY CUSTOMER CREATION PAYLOAD ===");
        console.log("Original Name:", session.user.name);
        console.log("Sanitized Name:", sanitizedName);
        console.log("Email:", session.user.email);
        console.log("==========================================");

        const customer = await razorpay.customers.create({
          name: sanitizedName,
          email: session.user.email,
        });

        razorpayCustomerId = customer.id;

        await prisma.user.update({
          where: { id: user.id },
          data: { razorpayCustomerId },
        });
      }

      // ==========================
      // DEBUG LOGS START
      // ==========================
      console.log("==========================================");
      console.log("CREATING RAZORPAY SUBSCRIPTION");
      console.log("Plan ID:", process.env.RAZORPAY_MONTHLY_PLAN_ID);
      console.log("Customer ID:", razorpayCustomerId);
      console.log("User ID:", user.id);
      console.log("==========================================");
      // ==========================

      // Create subscription
      const subscription = await razorpay.subscriptions.create({
        plan_id: process.env.RAZORPAY_MONTHLY_PLAN_ID as string,
        customer_notify: 1,
        total_count: 120,
        notes: {
          userId: user.id,
        },
      });

      // ==========================
      // DEBUG LOGS START
      // ==========================
      console.log("==========================================");
      console.log("RAZORPAY SUBSCRIPTION RESPONSE");
      console.dir(subscription, { depth: null });
      console.log("==========================================");
      // ==========================

      return NextResponse.json({
        provider: "razorpay",
        subscriptionId: subscription.id,
        key: process.env.RAZORPAY_KEY_ID,
      });

    } else {
      // Stripe Subscription
      let stripeCustomerId = user.stripeCustomerId;

      if (!stripeCustomerId) {
        const customer = await stripe.customers.create({
          email: session.user.email,
          name: session.user.name || "Reziyume User",
          metadata: {
            userId: user.id,
          },
        });

        stripeCustomerId = customer.id;

        await prisma.user.update({
          where: { id: user.id },
          data: {
            stripeCustomerId,
          },
        });
      }

      const checkoutSession = await stripe.checkout.sessions.create({
        customer: stripeCustomerId,
        mode: "subscription",
        payment_method_types: ["card"],
        line_items: [
          {
            price: process.env.STRIPE_MONTHLY_PRICE_ID,
            quantity: 1,
          },
        ],
        metadata: {
          userId: user.id,
        },
        subscription_data: {
          metadata: {
            userId: user.id,
          },
        },
        success_url: `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}/dashboard/payment/success`,
        cancel_url: `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}/dashboard/payment/cancel`,
      });

      return NextResponse.json({
        provider: "stripe",
        url: checkoutSession.url,
      });
    }

  } catch (error: any) {
    if (process.env.NODE_ENV === "development") {
      console.error("================ Payment Error [DEV] ================");
      console.error("Complete Payment Error Object:");
      console.dir(error, { depth: null });

      const devMessage =
        error?.error?.description ||
        error?.message ||
        error?.description ||
        JSON.stringify(error);

      return NextResponse.json(
        { error: devMessage },
        { status: 500 }
      );
    }

    console.error("Checkout error:", error);

    return NextResponse.json(
      { error: error.message || "Failed to create checkout session" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import crypto from "crypto";
import Razorpay from "razorpay";

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || !session.user?.email) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { razorpay_payment_id, razorpay_subscription_id, razorpay_signature } = await req.json();

    if (!razorpay_payment_id || !razorpay_subscription_id || !razorpay_signature) {
      return NextResponse.json({ error: "Missing required Razorpay parameters" }, { status: 400 });
    }

    const secret = process.env.RAZORPAY_KEY_SECRET as string;

    if (!secret) {
      console.error("RAZORPAY_KEY_SECRET is not configured");
      return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }

    // Verify signature using Razorpay's official subscription verification algorithm
    // signature = hmac_sha256(razorpay_payment_id + "|" + razorpay_subscription_id, secret);
    const generatedSignature = crypto
      .createHmac("sha256", secret)
      .update(`${razorpay_payment_id}|${razorpay_subscription_id}`)
      .digest("hex");

    if (generatedSignature !== razorpay_signature) {
      console.error("❌ Razorpay signature verification failed");
      return NextResponse.json({ error: "Invalid payment signature" }, { status: 400 });
    }

    // Fetch subscription from Razorpay to prevent replay attacks
    const razorpay = new Razorpay({
      key_id: process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID as string,
      key_secret: process.env.RAZORPAY_KEY_SECRET as string,
    });

    const subscription = await razorpay.subscriptions.fetch(razorpay_subscription_id);

    if (
      subscription.status !== "active" &&
      subscription.status !== "created" &&
      subscription.status !== "authenticated"
    ) {
      console.error("❌ Razorpay subscription is not active. Status:", subscription.status);
      return NextResponse.json({ error: "Subscription is not active" }, { status: 400 });
    }

    // Get the authenticated user from the database
    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    // NEW: Ensure the subscription actually belongs to the authenticated user!
    // We embedded the userId in the notes during checkout.
    if (subscription.notes?.userId !== user.id) {
      console.error(
        "❌ Cross-account upgrade attempt! Subscription belongs to",
        subscription.notes?.userId,
        "but session belongs to",
        user.id
      );
      return NextResponse.json(
        { error: "Subscription ownership verification failed" },
        { status: 403 }
      );
    }

    // Update user to PRO
    const isActivating = user.plan === "FREE";
    const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days approx. Webhook will sync exactly if it arrives.

    await prisma.user.update({
      where: { id: user.id },
      data: {
        plan: "PRO",
        razorpaySubscriptionId: razorpay_subscription_id,
        planExpiresAt: expiresAt,
        ...(isActivating ? { monthlyParseCount: 0 } : {}),
      },
    });

    console.log("✅ Synchronous verification successful. User upgraded to PRO.");

    return NextResponse.json({ success: true });

  } catch (error: any) {
    console.error("Razorpay synchronous verification error:", error);
    return NextResponse.json({ error: "Internal Error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || !session.user || !session.user.id) {
      return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
    }

    const { id } = await params;

    const resume = await prisma.resume.findUnique({
      where: {
        id,
      },
    });

    if (!resume) {
      return NextResponse.json({ message: "Resume not found" }, { status: 404 });
    }

    // Ensure the resume belongs to the logged-in user
    if (resume.userId !== session.user.id) {
      return NextResponse.json({ message: "Forbidden" }, { status: 403 });
    }

    return NextResponse.json({ resume });
  } catch (error) {
    console.error("Failed to fetch resume:", error);
    return NextResponse.json({ message: "Internal Server Error" }, { status: 500 });
  }
}

export async function PATCH(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || !session.user || !session.user.id) {
      return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
    }

    const { id } = await params;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const body = await req.json();

    // Verify ownership first
    const existingResume = await prisma.resume.findUnique({
      where: { id },
    });

    if (!existingResume) {
      return NextResponse.json({ message: "Resume not found" }, { status: 404 });
    }

    if (existingResume.userId !== session.user.id) {
      return NextResponse.json({ message: "Forbidden" }, { status: 403 });
    }

    // Update the resume with the provided data
    const updatedResume = await prisma.resume.update({
      where: { id },
      data: {
        name: body.name,
        templateId: body.templateId,
        contact: body.contact,
        summary: body.summary,
        experience: body.experience,
        education: body.education,
        skills: body.skills,
        projects: body.projects,
        customSections: body.customSections,
        sectionOrder: body.sectionOrder,
        sectionVisibility: body.sectionVisibility,
        formatting: body.formatting,
      },
    });

    return NextResponse.json({ resume: updatedResume });
  } catch (error) {
    console.error("Failed to update resume:", error);
    return NextResponse.json({ message: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { defaultResumeData } from "@/lib/types/resume";

export async function POST(req: Request) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || !session.user || !session.user.id) {
      return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
    }

    let templateId = defaultResumeData.templateId;
    try {
      const body = await req.json();
      if (body.templateId) {
        templateId = body.templateId;
      }
    } catch (_e) {
      // ignore JSON parse error if body is empty
    }

    // Create a new blank resume in the database
    const resume = await prisma.resume.create({
      data: {
        userId: session.user.id,
        name: defaultResumeData.name,
        templateId: templateId,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        contact: defaultResumeData.contact as any,
        summary: defaultResumeData.summary,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        experience: defaultResumeData.experience as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        education: defaultResumeData.education as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        skills: defaultResumeData.skills as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        projects: defaultResumeData.projects as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        customSections: defaultResumeData.customSections as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        sectionOrder: defaultResumeData.sectionOrder as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        sectionVisibility: defaultResumeData.sectionVisibility as any,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        formatting: defaultResumeData.formatting as any,
      },
    });

    return NextResponse.json({ resume }, { status: 201 });
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    console.error("Failed to create resume:", error);
    return NextResponse.json({ message: "Error: " + (error.message || String(error)) }, { status: 500 });
  }
}

export async function GET(_req: Request) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || !session.user || !session.user.id) {
      return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
    }

    // Fetch all resumes for this user, ordered by most recently updated
    const resumes = await prisma.resume.findMany({
      where: {
        userId: session.user.id,
      },
      orderBy: {
        updatedAt: "desc",
      },
      select: {
        id: true,
        name: true,
        templateId: true,
        updatedAt: true,
      },
    });

    return NextResponse.json({ resumes });
  } catch (error) {
    console.error("Failed to fetch resumes:", error);
    return NextResponse.json({ message: "Internal Server Error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { stripe } from "@/lib/stripe";
import prisma from "@/lib/prisma";

export async function POST(req: NextRequest) {
  const body = await req.text();
  const signature = req.headers.get("Stripe-Signature");

  if (!signature) {
    return NextResponse.json({ error: "No signature" }, { status: 400 });
  }

  let event;

  try {
    event = stripe.webhooks.constructEvent(
      body,
      signature,
      process.env.STRIPE_WEBHOOK_SECRET as string
    );
  } catch (err: any) {
    console.error("Stripe webhook verification failed:", err);
    return NextResponse.json({ error: "Verification failed" }, { status: 400 });
  }

  try {
    switch (event.type) {
      case "checkout.session.completed":
      case "invoice.payment_succeeded": {
        // Activation / Renewal
        const data = event.data.object as any;
        const subscriptionId = data.subscription;

        let userId = data.metadata?.userId;
        if (!userId && data.subscription_details?.metadata?.userId) {
           userId = data.subscription_details.metadata.userId;
        }

        if (subscriptionId) {
          const subscription = await stripe.subscriptions.retrieve(subscriptionId);
          // Only fetch user id from subscription if not available in current object
          if (!userId && subscription.metadata?.userId) {
            userId = subscription.metadata.userId;
          }

          if (userId) {
            const currentPeriodEnd = new Date((subscription as any).current_period_end * 1000);

            // Check state for idempotency: if user is FREE -> reset monthlyParseCount
            const user = await prisma.user.findUnique({ where: { id: userId } });
            if (user) {
              const isActivating = user.plan === "FREE";

              await prisma.user.update({
                where: { id: userId },
                data: {
                  plan: "PRO",
                  stripeSubscriptionId: subscriptionId,
                  planExpiresAt: currentPeriodEnd,
                  ...(isActivating ? { monthlyParseCount: 0 } : {}),
                },
              });
            }
          }
        }
        break;
      }

      case "customer.subscription.deleted": {
        const subscription = event.data.object as any;
        const userId = subscription.metadata?.userId;

        if (userId) {
          await prisma.user.update({
            where: { id: userId },
            data: {
              plan: "FREE",
              // We do not clear planExpiresAt. They keep access until JIT expiration catches them.
            },
          });
        }
        break;
      }
    }
  } catch (err) {
    console.error("Webhook processing error:", err);
    return NextResponse.json({ error: "Internal Error" }, { status: 500 });
  }

  return NextResponse.json({ received: true });
}

import { StyleSheet, Font } from '@react-pdf/renderer';
