      alignItems: 'center',
      backgroundColor: activeColors.primary,
      height: 28,
      paddingLeft: 8,
      paddingRight: 8,
      marginBottom: 8,
    },
    sectionHeadingSolidText: {
      fontFamily: getFontFamily(config.fonts.heading),
      fontSize: fontSizes.heading,
      fontWeight: 'bold',
      color: activeColors.background,
    },
    sectionHeadingUnderlined: {
      fontFamily: getFontFamily(config.fonts.heading),
      fontSize: fontSizes.heading,
      fontWeight: 'bold',
      color: activeColors.primary,
      borderBottomWidth: 2,
      borderBottomColor: activeColors.primary,
      paddingBottom: 4,
      marginBottom: 8,
    },
    sectionHeadingUppercase: {
      fontFamily: getFontFamily(config.fonts.heading),
      fontSize: fontSizes.heading,
      fontWeight: 'bold',
      color: activeColors.primary,
      textTransform: 'uppercase',
      letterSpacing: 1,
      marginBottom: 8,
    },
    sectionHeadingDefault: {
      fontFamily: getFontFamily(config.fonts.heading),
      fontSize: fontSizes.heading,
      fontWeight: 'bold',
      color: activeColors.primary,
      marginBottom: 8,
    },

    // Core Layout
    columnSidebar: {
      width: '33.33%',
