      borderColor: activeColors.primary,
    },
    headerContainer: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: 24,
    },
    headerTextContainer: {
    },
    nameText: {
      fontFamily: getFontFamily(config.fonts.heading),
      fontSize: fontSizes.name,
      fontWeight: 'bold',
      letterSpacing: -0.5,
      color: activeColors.primary,
    },
    jobTitleText: {
