  );
};

import React from 'react';
import { Page, View, Image, Text, Link } from '@react-pdf/renderer';
import { ResumeData, hasProfilePhoto } from '@/lib/types/resume';
import { TemplateConfig } from '../../studio/preview/templates/registry';
import { createPdfStyles } from '../PdfShared';
import { PdfMainContent } from './PdfMainContent';
import { PdfHeader } from './PdfHeader';

interface PdfHeaderLayoutProps {
  data: ResumeData;
  config: TemplateConfig;
}

export const PdfHeaderLayout = ({ data, config }: PdfHeaderLayoutProps) => {
  const styles = createPdfStyles(config, data.formatting);
  const { layout, colors } = config;

  const isSplitHeader = layout === 'split-header';
  const isPhotoBanner = layout === 'photo-banner';
  const isPhotoCard = layout === 'photo-card';
  const isPhotoElegant = layout === 'photo-elegant';
  const isPhotoTopRight = layout === 'photo-top-right';

  const renderCustomHeader = () => {
    // Basic wrapper with background for card/banner
    const headerStyle: any = {
      padding: 40,
      paddingBottom: 20,
    };

    if (isPhotoCard) {
      // Linear gradient approximation with a light background
      headerStyle.backgroundColor = '#f8fafc'; 
    }

    if (isPhotoTopRight || isSplitHeader) {
      return (
        <View style={[{ padding: 40, paddingBottom: 20, flexDirection: 'row', justifyContent: 'space-between' }]}>
          <View style={{ flex: 1 }}>
            <PdfHeader data={data} config={config} showPhoto={false} />
          </View>
          {hasProfilePhoto(data) && (
            <Image src={data.contact.photoBase64} style={[styles.photo, { marginLeft: 20, marginRight: 0 }]} />
          )}
        </View>
      );
    }

    // Centered variants (banner, elegant)
    if (isPhotoBanner || isPhotoElegant) {
      return (
        <View style={{ padding: 40, paddingBottom: 20, alignItems: 'center' }}>
          <PdfHeader data={data} config={config} align="center" showPhoto={hasProfilePhoto(data)} />
        </View>
      );
    }

    // Default fallback to card style
    return (
      <View style={headerStyle}>
        <PdfHeader data={data} config={config} align="left" showPhoto={hasProfilePhoto(data)} />
      </View>
    );
  };

  return (
    <Page size="A4" style={[styles.page, { padding: 0 }]}>
      {renderCustomHeader()}
      {isSplitHeader && <View style={[styles.headerDivider, { marginHorizontal: 40, marginTop: 0 }]} />}
      {isPhotoElegant && <View style={[styles.headerDivider, { marginHorizontal: 40, marginTop: 10, alignSelf: 'center', width: '80%' }]} />}
      <View style={{ padding: 40, paddingTop: 10 }}>
        <PdfMainContent data={data} config={config} />
      </View>
    </Page>
  );
};

import React from 'react';
import { ResumeData, hasProfilePhoto } from '@/lib/types/resume';
import { TemplateConfig } from '../../studio/preview/templates/registry';
import { PdfSummary } from '../PdfSummary';
import { PdfExperience } from '../PdfExperience';
import { PdfEducation } from '../PdfEducation';
import { PdfSkills } from '../PdfSkills';
import { PdfProjects } from '../PdfProjects';
import { PdfCustomSections } from '../PdfCustomSections';

interface PdfMainContentProps {
  data: ResumeData;
  config: TemplateConfig;
  sections?: string[]; // Optional override for two-column splits
}

export const PdfMainContent = ({ data, config, sections = data.sectionOrder }: PdfMainContentProps) => {
  const sectionsToRender = sections || ['experience', 'education', 'skills', 'projects', 'customSections'];

  return (
    <>
      <PdfSummary summary={data.summary} config={config} formatting={data.formatting} />
      {sectionsToRender.map((sectionId) => {
        if ((data.sectionVisibility as Record<string, boolean>)?.[sectionId] === false) return null;

        switch (sectionId) {
          case 'experience':
            return <PdfExperience key="experience" experience={data.experience} config={config} formatting={data.formatting} />;
          case 'education':
            return <PdfEducation key="education" education={data.education} config={config} formatting={data.formatting} />;
          case 'skills':
            return <PdfSkills key="skills" skills={data.skills} config={config} formatting={data.formatting} />;
          case 'projects':
            return <PdfProjects key="projects" projects={data.projects} config={config} formatting={data.formatting} />;
          case 'customSections':
            return <PdfCustomSections key="custom" customSections={data.customSections} config={config} formatting={data.formatting} />;
          default:
            return null;
        }
      })}
    </>
  );
};

