        style={{
          background: "rgba(240,238,250,0.95)",
          backdropFilter: "blur(24px)",
          border: "1px solid rgba(255,255,255,0.7)",
          boxShadow: "20px 20px 60px rgba(30,27,50,0.25), -10px -10px 30px rgba(255,255,255,0.5)"
